        grps={}
        for r,c in cells: grps.setdefault(r-c,[]).append((r,c))
        for kk,group in grps.items():
            group=sorted(set(group))
            a,b=min(group),max(group)
            dr=b[0]-a[0]; dc=b[1]-a[1]
