def f(g):
    import numpy as np
    g=np.array(g); H,W=g.shape
    vals,_=np.unique(g,return_counts=True); order=[x for x,_ in sorted(zip(vals[::-1],vals))]
    out=g.copy()
    for r in range(H):
        for c in range(W):
            nb=g[max(0,r-1):min(H,r+2),max(0,c-1):min(W,c+2)].reshape(-1)
            # exclude self
            mask=nb!=g[r,c]
            if mask.sum()>0:
                best,v=np.bincount(nb[mask]).argmax(),np.bincount(nb[mask]).max()
                if v==g[r,c].max(): pass
            else: continue
            nbv=Counter(int(x) for x in nb if int(x)!=g[r,c])
            if nbv:
                m=max(nbv.values())
                cand=[k for k,vv in nbv.items() if vv==m]
                new=cand[0] if len(cand)==1 else min(cand)
                out[r][c]=new
    return out.tolist()
